import{_ as d,c as e,o,b2 as r}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"监控审计（操作日志 / 登录日志 / 在线用户）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/monitor-audit.md","filePath":"docs/backend/modules/monitor-audit.md"}'),a={name:"docs/backend/modules/monitor-audit.md"};function l(c,t,i,n,h,s){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="监控审计-操作日志-登录日志-在线用户" tabindex="-1">监控审计（操作日志 / 登录日志 / 在线用户） <a class="header-anchor vp-link" href="#监控审计-操作日志-登录日志-在线用户" aria-label="Permalink to &quot;监控审计（操作日志 / 登录日志 / 在线用户）&quot;">​</a></h1><h2 id="操作日志" tabindex="-1">操作日志 <a class="header-anchor vp-link" href="#操作日志" aria-label="Permalink to &quot;操作日志&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysOperLogController</code></td></tr><tr><td>路径</td><td><code>/monitor/operlog</code></td></tr><tr><td>前端</td><td><code>views/monitor/operlog/index.vue</code></td></tr><tr><td>采集</td><td><code>quickboot-common</code> <code>monitor.operlog</code> AOP</td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>分页查询</td></tr><tr><td>GET <code>/{operId}</code></td><td>详情</td></tr><tr><td>POST <code>/export</code></td><td>导出</td></tr><tr><td>POST <code>/remove</code></td><td>删除</td></tr><tr><td>POST <code>/clean</code></td><td>清空</td></tr></tbody></table></div><p>配置（<code>application.yml</code>）：</p><ul><li><code>qc.monitor.operlog.enabled</code>：是否采集</li><li><code>qc.monitor.operlog.async</code>：异步落库</li><li><code>qc.monitor.operlog.export-limit</code>：导出上限</li></ul><p>Controller 方法可用 <code>@IgnoreLogger</code> 排除采集。</p><hr><h2 id="登录日志" tabindex="-1">登录日志 <a class="header-anchor vp-link" href="#登录日志" aria-label="Permalink to &quot;登录日志&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysLogininforController</code></td></tr><tr><td>路径</td><td><code>/monitor/logininfor</code></td></tr><tr><td>前端</td><td><code>views/monitor/logininfor/index.vue</code></td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>分页</td></tr><tr><td>POST <code>/export</code></td><td>导出</td></tr><tr><td>POST <code>/remove</code>、<code>/clean</code></td><td>删除/清空</td></tr><tr><td>GET <code>/unlock/{userName}</code></td><td>解锁用户（登录失败锁定场景）</td></tr></tbody></table></div><hr><h2 id="在线用户" tabindex="-1">在线用户 <a class="header-anchor vp-link" href="#在线用户" aria-label="Permalink to &quot;在线用户&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysUserOnlineController</code></td></tr><tr><td>路径</td><td><code>/monitor/online</code></td></tr><tr><td>前端</td><td><code>views/monitor/online/index.vue</code></td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>当前会话列表（Sa-Token）</td></tr><tr><td>POST <code>/forceLogout</code></td><td>强退</td></tr></tbody></table></div><p>会话记录依赖 <code>OnlineSessionRecorder</code> 与 Token 存储（local/redis）。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./security-module.html" class="vp-link">安全防护</a></li><li><a href="./job-scheduler.html" class="vp-link">定时任务</a></li></ul>',18)])])}const m=d(a,[["render",l]]);export{p as __pageData,m as default};
